INSERT IGNORE INTO cloud_flow_db.wf_template (id, name, description, category_id, tags, definition, is_system, status, created_by, tenant_id) VALUES
('tpl-incident-001', 'IT故障处理', '自动分级 → 按级别分流 → 处理 → 验证确认', 'cat-it',
'["IT故障","IT运维","模板"]',
'{
  "nodes": [
    {
      "id": "start",
      "type": "START",
      "title": "提交故障报告"
    },
    {
      "id": "inc_n1",
      "type": "SCRIPT",
      "title": "自动故障分级",
      "props": {
        "scriptType": "GROOVY",
        "scriptContent": "def level = severity >= 8 ? \\\"P1\\\" : severity >= 5 ? \\\"P2\\\" : \\\"P3\\\"; return [incidentLevel: level]",
        "continueOnError": false
      },
      "branchStrategy": "EXCLUSIVE"
    },
    {
      "id": "inc_n7",
      "type": "MANUAL",
      "title": "报修人验证确认",
      "approverType": "INITIATOR",
      "props": {
        "taskDescription": "请确认故障是否已修复，如未修复请退回重新处理",
        "priority": "MEDIUM"
      }
    },
    {
      "id": "inc_n8",
      "type": "NOTIFICATION",
      "title": "通知故障关闭",
      "props": {
        "recipientType": "INITIATOR",
        "notificationTitle": "故障处理完成",
        "notificationContent": "您提交的故障报告已处理完成并关闭。"
      }
    },
    {
      "id": "inc_end",
      "type": "END",
      "title": "流程结束"
    },
    {
      "id": "inc_b1",
      "type": "CONDITION",
      "title": "P1 紧急故障",
      "condition": "incidentLevel == \\\"P1\\\""
    },
    {
      "id": "inc_n2",
      "type": "NOTIFICATION",
      "title": "紧急通知管理层",
      "props": {
        "recipientType": "ROLE",
        "recipientValue": "manager",
        "notificationTitle": "【紧急】P1级故障告警",
        "notificationContent": "系统发生P1级紧急故障，请立即关注！故障描述: ${description}"
      }
    },
    {
      "id": "inc_n3",
      "type": "MANUAL",
      "title": "紧急修复处理",
      "approverType": "ROLE",
      "approverValue": "admin",
      "props": {
        "taskDescription": "P1级紧急故障，需立即响应并修复",
        "priority": "HIGH"
      }
    },
    {
      "id": "inc_b2",
      "type": "CONDITION",
      "title": "P2 重要故障",
      "condition": "incidentLevel == \\\"P2\\\""
    },
    {
      "id": "inc_n4",
      "type": "APPROVAL",
      "title": "运维主管派单",
      "approverType": "ROLE",
      "approverValue": "admin"
    },
    {
      "id": "inc_n5",
      "type": "MANUAL",
      "title": "运维工程师处理",
      "approverType": "ROLE",
      "approverValue": "admin",
      "props": {
        "taskDescription": "P2级故障，请在4小时内完成修复",
        "priority": "MEDIUM"
      }
    },
    {
      "id": "inc_b3",
      "type": "CONDITION",
      "title": "P3 一般故障",
      "condition": "incidentLevel == \\\"P3\\\""
    },
    {
      "id": "inc_n6",
      "type": "MANUAL",
      "title": "运维工程师处理",
      "approverType": "ROLE",
      "approverValue": "admin",
      "props": {
        "taskDescription": "P3级一般故障，请在24小时内处理",
        "priority": "LOW"
      }
    }
  ],
  "edges": [
    {
      "id": "start->inc_n1",
      "source": "start",
      "target": "inc_n1"
    },
    {
      "id": "inc_n1->inc_n7",
      "source": "inc_n1",
      "target": "inc_n7",
      "isDefault": true
    },
    {
      "id": "inc_n7->inc_n8",
      "source": "inc_n7",
      "target": "inc_n8"
    },
    {
      "id": "inc_n8->inc_end",
      "source": "inc_n8",
      "target": "inc_end"
    },
    {
      "id": "inc_n1->inc_b1",
      "source": "inc_n1",
      "target": "inc_b1",
      "condition": "incidentLevel == \\\"P1\\\""
    },
    {
      "id": "inc_b1->inc_n2",
      "source": "inc_b1",
      "target": "inc_n2"
    },
    {
      "id": "inc_n2->inc_n3",
      "source": "inc_n2",
      "target": "inc_n3"
    },
    {
      "id": "inc_n3->inc_n7",
      "source": "inc_n3",
      "target": "inc_n7"
    },
    {
      "id": "inc_n1->inc_b2",
      "source": "inc_n1",
      "target": "inc_b2",
      "condition": "incidentLevel == \\\"P2\\\""
    },
    {
      "id": "inc_b2->inc_n4",
      "source": "inc_b2",
      "target": "inc_n4"
    },
    {
      "id": "inc_n4->inc_n5",
      "source": "inc_n4",
      "target": "inc_n5"
    },
    {
      "id": "inc_n5->inc_n7",
      "source": "inc_n5",
      "target": "inc_n7"
    },
    {
      "id": "inc_n1->inc_b3",
      "source": "inc_n1",
      "target": "inc_b3",
      "condition": "incidentLevel == \\\"P3\\\""
    },
    {
      "id": "inc_b3->inc_n6",
      "source": "inc_b3",
      "target": "inc_n6"
    },
    {
      "id": "inc_n6->inc_n7",
      "source": "inc_n6",
      "target": "inc_n7"
    }
  ]
}',
1, 'active', 'system', NULL);

