INSERT IGNORE INTO cloud_flow_db.wf_template (id, name, description, category_id, tags, definition, is_system, status, created_by, tenant_id) VALUES
('tpl-safety_incident-001', '安全事故处理', '自动记录 → 并行处置+通知 → 事故调查 → 整改审批', 'cat-industry',
'["安全事故","行业专属","模板"]',
'{
  "nodes": [
    {
      "id": "start",
      "type": "START",
      "title": "报告安全事故"
    },
    {
      "id": "sf_n1",
      "type": "SCRIPT",
      "title": "自动记录事故信息",
      "props": {
        "scriptType": "GROOVY",
        "scriptContent": "def summary = (accidentType ?: \\\"未知事故\\\") + \\\"@\\\" + (location ?: \\\"未知地点\\\"); return [accidentRecorded: true, accidentSummary: summary]",
        "continueOnError": true
      }
    },
    {
      "id": "sf_n2",
      "type": "PARALLEL",
      "title": "并行处置（现场+通知）",
      "approverType": "ROLE",
      "approverValue": "admin",
      "branchStrategy": "PARALLEL"
    },
    {
      "id": "sf_n5",
      "type": "APPROVAL",
      "title": "事故调查报告审核",
      "approverType": "ROLE",
      "approverValue": "manager"
    },
    {
      "id": "sf_n6",
      "type": "APPROVAL",
      "title": "整改方案审批",
      "approverType": "ROLE",
      "approverValue": "manager"
    },
    {
