INSERT IGNORE INTO cloud_flow_db.wf_template (id, name, description, category_id, tags, definition, is_system, status, created_by, tenant_id) VALUES
('tpl-leave_advanced-001', '请假全流程', '天数判断 → 分级审批 → 交接确认 → 定时提醒 → 通知', 'cat-hr',
'["请假","人事","模板"]',
'{
  "nodes": [
    {
      "id": "start",
      "type": "START",
      "title": "提交请假申请"
    },
    {
      "id": "la_n1",
      "type": "APPROVAL",
      "title": "直属上级审批",
      "approverType": "DIRECT_LEADER",
      "branchStrategy": "EXCLUSIVE"
    },
    {
      "id": "la_n5",
      "type": "MANUAL",
      "title": "发起人确认工作交接",
      "approverType": "INITIATOR",
      "props": {
        "taskDescription": "请在休假前完成工作交接，并确认交接安排已同步给相关同事。",
        "priority": "MEDIUM"
      }
    },
    {
      "id": "la_n6",
      "type": "TIMER",
      "title": "假期结束前1天提醒",
      "props": {
        "timerType": "DELAY",
        "delayMinutes": 1
      }
    },
    {
      "id": "la_n7",
      "type": "NOTIFICATION",
      "title": "通知请假结果",
      "props": {
        "recipientType": "INITIATOR",
        "notificationTitle": "请假审批结果",
        "notificationContent": "您的请假申请（${days}天）已审批通过，请做好工作交接。"
      }
    },
    {
      "id": "la_end",
      "type": "END",
      "title": "流程结束"
    },
    {
      "id": "la_b1",
      "type": "CONDITION",
      "title": "请假 ≤ 3天",
      "condition": "days <= 3"
    },
    {
      "id": "la_b2",
      "type": "CONDITION",
      "title": "3天 < 请假 ≤ 7天",
      "condition": "days > 3 && days <= 7"
    },
    {
      "id": "la_n2",
      "type": "APPROVAL",
      "title": "部门经理审批",
      "approverType": "DEPT_MANAGER"
    },
    {
      "id": "la_b3",
      "type": "CONDITION",
      "title": "请假 > 7天",
      "condition": "days > 7"
    },
    {
      "id": "la_n3",
      "type": "APPROVAL",
      "title": "部门经理审批",
      "approverType": "DEPT_MANAGER"
    },
    {
      "id": "la_n4",
      "type": "APPROVAL",
      "title": "总经理审批",
      "approverType": "ROLE",
      "approverValue": "manager"
    }
  ],
  "edges": [
    {
      "id": "start->la_n1",
      "source": "start",
      "target": "la_n1"
    },
    {
      "id": "la_n1->la_n5",
      "source": "la_n1",
      "target": "la_n5",
      "isDefault": true
    },
    {
      "id": "la_n5->la_n6",
      "source": "la_n5",
      "target": "la_n6"
    },
    {
      "id": "la_n6->la_n7",
      "source": "la_n6",
      "target": "la_n7"
    },
    {
      "id": "la_n7->la_end",
      "source": "la_n7",
      "target": "la_end"
    },
    {
      "id": "la_n1->la_b1",
      "source": "la_n1",
      "target": "la_b1",
      "condition": "days <= 3"
    },
    {
      "id": "la_n1->la_b2",
      "source": "la_n1",
      "target": "la_b2",
      "condition": "days > 3 && days <= 7"
    },
    {
      "id": "la_b1->la_n5",
      "source": "la_b1",
      "target": "la_n5"
    },
    {
      "id": "la_b2->la_n2",
      "source": "la_b2",
      "target": "la_n2"
    },
    {
      "id": "la_n2->la_n5",
      "source": "la_n2",
      "target": "la_n5"
    },
    {
      "id": "la_n1->la_b3",
      "source": "la_n1",
      "target": "la_b3",
      "condition": "days > 7"
    },
    {
      "id": "la_b3->la_n3",
      "source": "la_b3",
      "target": "la_n3"
    },
    {
      "id": "la_n3->la_n4",
      "source": "la_n3",
      "target": "la_n4"
    },
    {
      "id": "la_n4->la_n5",
      "source": "la_n4",
      "target": "la_n5"
    }
  ]
}',
1, 'active', 'system', NULL);

INSERT IGNORE INTO cloud_flow_db.wf_template (id, name, description, category_id, tags, definition, is_system, status, created_by, tenant_id) VALUES
('tpl-deployment-001', '生产环境发布', '代码审查 → 自动构建 → 等待窗口 → 并行部署+监控 → 验证', 'cat-it',
'["生产环境发布","IT运维","模板"]',
'{
  "nodes": [
    {
      "id": "start",
      "type": "START",
      "title": "提交发布申请"
    },
    {
      "id": "dep_n1",
      "type": "APPROVAL",
      "title": "技术负责人代码审查",
      "approverType": "ROLE",
      "approverValue": "admin"
    },
    {
      "id": "dep_n2",
      "type": "SCRIPT",
      "title": "自动构建与测试",
      "props": {
        "scriptType": "GROOVY",
        "scriptContent": "return [buildStatus: \\\"SUCCESS\\\", buildBranch: branch, buildVersion: version, buildFinishedAt: System.currentTimeMillis()]",
        "continueOnError": false
      }
    },
    {
      "id": "dep_n3",
      "type": "APPROVAL",
      "title": "发布审批",
      "approverType": "ROLE",
      "approverValue": "manager"
    },
    {
      "id": "dep_n4",
      "type": "TIMER",
      "title": "等待发布窗口",
      "props": {
        "timerType": "DELAY",
        "delayMinutes": 1
      }
    },
    {
      "id": "dep_n5",
      "type": "PARALLEL",
      "title": "并行执行（部署+监控）",
      "approverType": "ROLE",
      "approverValue": "admin",
      "branchStrategy": "PARALLEL"
    },
    {
      "id": "dep_n8",
      "type": "MANUAL",
      "title": "发布后验证确认",
      "approverType": "ROLE",
      "approverValue": "admin",
      "props": {
        "taskDescription": "验证发布后系统功能正常，检查关键业务指标",
        "priority": "HIGH"
      }
    },
    {
      "id": "dep_n9",
      "type": "NOTIFICATION",
      "title": "通知发布完成",
      "props": {
        "recipientType": "INITIATOR",
        "notificationTitle": "发布完成通知",
        "notificationContent": "版本 ${version} 已成功发布到生产环境。"
      }
    },
    {
      "id": "dep_end",
      "type": "END",
      "title": "流程结束"
    },
    {
      "id": "dep_b1",
      "type": "CONDITION",
      "title": "执行部署"
    },
    {
      "id": "dep_n6",
      "type": "SCRIPT",
      "title": "执行自动部署",
      "props": {
        "scriptType": "GROOVY",
        "scriptContent": "return [deployStatus: \\\"SUCCESS\\\", deployedVersion: version, deployedAt: System.currentTimeMillis()]",
        "continueOnError": false
      }
    },
    {
      "id": "dep_b2",
      "type": "CONDITION",
      "title": "监控告警"
    },
    {
      "id": "dep_n7",
      "type": "NOTIFICATION",
      "title": "通知运维团队监控",
      "props": {
        "recipientType": "ROLE",
        "recipientValue": "admin",
        "notificationTitle": "发布监控通知",
        "notificationContent": "版本 ${version} 正在发布，请密切关注系统监控指标。"
      }
    }
  ],
  "edges": [
    {
      "id": "start->dep_n1",
      "source": "start",
      "target": "dep_n1"
    },
    {
      "id": "dep_n1->dep_n2",
      "source": "dep_n1",
      "target": "dep_n2"
    },
    {
      "id": "dep_n2->dep_n3",
      "source": "dep_n2",
      "target": "dep_n3"
    },
    {
      "id": "dep_n3->dep_n4",
      "source": "dep_n3",
      "target": "dep_n4"
    },
    {
      "id": "dep_n4->dep_n5",
      "source": "dep_n4",
      "target": "dep_n5"
    },
    {
      "id": "dep_n5->dep_n8",
      "source": "dep_n5",
      "target": "dep_n8",
      "isDefault": true
    },
    {
      "id": "dep_n8->dep_n9",
      "source": "dep_n8",
      "target": "dep_n9"
    },
    {
      "id": "dep_n9->dep_end",
      "source": "dep_n9",
      "target": "dep_end"
    },
    {
      "id": "dep_n5->dep_b1",
      "source": "dep_n5",
      "target": "dep_b1"
    },
    {
      "id": "dep_b1->dep_n6",
      "source": "dep_b1",
      "target": "dep_n6"
    },
    {
      "id": "dep_n5->dep_b2",
      "source": "dep_n5",
      "target": "dep_b2"
    },
    {
      "id": "dep_b2->dep_n7",
      "source": "dep_b2",
      "target": "dep_n7"
    }
  ]
}',
1, 'active', 'system', NULL);

