INSERT IGNORE INTO cloud_flow_db.sys_log (
  log_id, tenant_id, log_type, title, service_id, remote_addr, user_agent, request_uri, method, params, time, exception, create_by, create_time
)
SELECT
  92000 + n,
  100000,
  CASE WHEN n % 10 = 0 THEN '9' ELSE '0' END,
  CONCAT('批量演示日志', n),
  'cloudflow-service-oa',
  CONCAT('10.10.1.', LPAD(n % 200, 2, '0')),
  'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/134.0.0.0 Safari/537.36',
  '/api/demo/batch',
  'GET',
  CONCAT('{"page":', n, ',"size":20}'),
  50 + (n % 200),
  CASE WHEN n % 10 = 0 THEN '批量异常示例' ELSE NULL END,
  'admin',
  DATE_SUB(NOW(), INTERVAL n MINUTE)
FROM (
  SELECT (a.n * 100 + b.n * 10 + c.n) + 1 AS n
  FROM (SELECT 0 AS n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) a
  CROSS JOIN (SELECT 0 AS n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) b
  CROSS JOIN (SELECT 0 AS n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) c
  WHERE (a.n * 100 + b.n * 10 + c.n) < 300
) seq;

INSERT IGNORE INTO cloud_flow_db.sys_audit_log (
    audit_id, tenant_id, biz_module, audit_name, audit_field, before_val, after_val,
    before_json, after_json, diff_json, high_risk, risk_level, create_by, create_time
  )
  SELECT
    92000 + n,
    100000,
    'workflow',
    '批量审计记录',
    'status',
    'draft',
    CASE WHEN n % 2 = 0 THEN 'published' ELSE 'archived' END,
    JSON_OBJECT('status', 'draft'),
    JSON_OBJECT('status', CASE WHEN n % 2 = 0 THEN 'published' ELSE 'archived' END),
    JSON_ARRAY(JSON_OBJECT('op', 'replace', 'path', '/status', 'from', 'draft', 'value',
      CASE WHEN n % 2 = 0 THEN 'published' ELSE 'archived' END)),
    0,
    'NORMAL',
    'admin',
    DATE_SUB(NOW(), INTERVAL n MINUTE)
  FROM (
  SELECT (a.n * 100 + b.n * 10 + c.n) + 1 AS n
  FROM (SELECT 0 AS n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) a
  CROSS JOIN (SELECT 0 AS n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) b
  CROSS JOIN (SELECT 0 AS n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) c
  WHERE (a.n * 100 + b.n * 10 + c.n) < 300
) seq;

